import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../providers/media_provider.dart';
class StatsScreen extends StatelessWidget{const StatsScreen({super.key});@override Widget build(BuildContext context){final s=context.watch<MediaProvider>().stats;return ListView(padding:const EdgeInsets.all(16),children:[_card('تمت المشاهدة',s.totalWatched.toString()),_card('قيد المشاهدة',s.totalWatching.toString()),_card('قائمة الانتظار',s.totalWatchlist.toString()),_card('ساعات المشاهدة',s.totalHours.toStringAsFixed(1)),_card('متوسط تقييمي',s.averageRating.toStringAsFixed(1)),const SizedBox(height:12),Text('الأنواع الأكثر مشاهدة',style:Theme.of(context).textTheme.titleLarge),...s.topGenres.entries.map((e)=>ListTile(title:Text(e.key),trailing:Text(e.value.toString()))),Text('الممثلون الأكثر ظهوراً',style:Theme.of(context).textTheme.titleLarge),...s.topActors.entries.map((e)=>ListTile(title:Text(e.key),trailing:Text(e.value.toString())))]);}Widget _card(String a,String b)=>Card(child:ListTile(title:Text(a),trailing:Text(b,style:const TextStyle(fontSize:20,fontWeight:FontWeight.bold))));}
